Author: hkjang <gagagiga@naver.com>
Date:   Mon Sep 21 04:31:38 2026 +0900

    Block unfinished job results after restart

package jobs

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"sync"
	"time"

	"pii-masker/internal/core"
)

type Store struct {
	root string
	mu   sync.RWMutex
	jobs map[string]*core.JobRecord
}

func New(root string) (*Store, error) {
	store := &Store{
		root: filepath.Join(root, "jobs"),
		jobs: map[string]*core.JobRecord{},
	}
	if err := os.MkdirAll(store.root, 0o755); err != nil {
		return nil, fmt.Errorf("failed to create jobs dir: %w", err)
	}
	if err := store.load(); err != nil {
		return nil, err
	}
	return store, nil
}

// Create records a new job. The uploaded input is written to the job directory
// before the record exists, so a record that cannot be persisted takes the
// directory down with it: a directory without a valid job.json is unreachable
// through the API and would otherwise keep the original document until the next
// start removes it.
func (s *Store) Create(job *core.JobRecord) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.jobs[job.ID] = cloneJob(job)
	if err := s.persistLocked(job.ID); err != nil {
		delete(s.jobs, job.ID)
		if job.ID != "" {
			_ = os.RemoveAll(filepath.Join(s.root, job.ID))
		}
		return err
	}
	return nil
}

func (s *Store) Save(job *core.JobRecord) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.jobs[job.ID] = cloneJob(job)
	return s.persistLocked(job.ID)
}

func (s *Store) Get(id string) (*core.JobRecord, bool, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	job, ok := s.jobs[id]
	if !ok {
		return nil, false, nil
	}
	return cloneJob(job), true, nil
}

func (s *Store) List(limit int) ([]core.JobRecord, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	items := make([]core.JobRecord, 0, len(s.jobs))
	for _, job := range s.jobs {
		items = append(items, *cloneJob(job))
	}
	sort.Slice(items, func(i, j int) bool {
		return items[i].Metadata.UpdatedAt.After(items[j].Metadata.UpdatedAt)
	})
	if limit > 0 && len(items) > limit {
		items = items[:limit]
	}
	return items, nil
}

// DeleteExpired removes every job whose last update is older than cutoff, along with
// the uploaded and masked files it kept on disk, and returns the ids that were dropped.
// Queued and running jobs are always kept regardless of age, because their runner still
// has to read the stored input back when a slot frees up. A job whose directory cannot
// be removed stays in the store so the next sweep retries it.
func (s *Store) DeleteExpired(cutoff time.Time) ([]string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	deleted := make([]string, 0)
	var firstErr error
	for id, job := range s.jobs {
		if job.Metadata.Status == "queued" || job.Metadata.Status == "running" {
			continue
		}
		if !job.Metadata.UpdatedAt.Before(cutoff) {
			continue
		}
		if err := os.RemoveAll(filepath.Join(s.root, id)); err != nil {
			if firstErr == nil {
				firstErr = fmt.Errorf("failed to remove job %s: %w", id, err)
			}
			continue
		}
		delete(s.jobs, id)
		deleted = append(deleted, id)
	}
	sort.Strings(deleted)
	return deleted, firstErr
}

func (s *Store) WriteInputFile(jobID, filename string, content []byte) (string, error) {
	return s.writeFile(jobID, "input_"+filename, content)
}

func (s *Store) WriteOutputFile(jobID, filename string, content []byte) (string, error) {
	return s.writeFile(jobID, "output_"+filename, content)
}

func (s *Store) writeFile(jobID, filename string, content []byte) (string, error) {
	jobDir := filepath.Join(s.root, jobID)
	if err := os.MkdirAll(jobDir, 0o755); err != nil {
		return "", err
	}
	fullPath := filepath.Join(jobDir, filename)
	if err := os.WriteFile(fullPath, content, 0o644); err != nil {
		return "", err
	}
	return fullPath, nil
}

// load reads every stored job back into memory. A job that was still queued or
// running when the process stopped cannot be resumed, so it is recorded as
// interrupted and that transition is written back to disk.
//
// The interrupted record deliberately keeps the timestamp the job last had.
// Moving it to the current time would push the retention deadline of the stored
// upload - the original, unmasked document - a full retention window into the
// future, and because the transition happens on every start a service that
// restarts more often than that would keep those files forever.
//
// A directory without a readable job.json, or whose record names another job, is
// removed instead of skipped. The upload was written before the record, so a crash
// or a full disk in between leaves exactly such a directory behind, and one that is
// never loaded is never looked up, never listed and never reached by the retention
// sweep, which deletes by job id. Nothing can still use the document it holds.
// Because a record is replaced by rename (see persistLocked), a damaged job.json
// only arises when no record was ever completed, never from a later save.
func (s *Store) load() error {
	s.mu.Lock()
	defer s.mu.Unlock()

	entries, err := os.ReadDir(s.root)
	if err != nil {
		return fmt.Errorf("failed to read jobs dir: %w", err)
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		jobDir := filepath.Join(s.root, entry.Name())
		job, ok := readJobRecord(jobDir, entry.Name())
		if !ok {
			if err := os.RemoveAll(jobDir); err != nil {
				log.Printf("failed to remove orphaned job directory %s: %v", jobDir, err)
			} else {
				log.Printf("removed orphaned job directory %s", jobDir)
			}
			continue
		}
		job.InputPath = firstExistingFile(jobDir, "input_")
		// A leftover output is not proof that writing and completion succeeded.
		if job.Metadata.Status == "completed" {
			job.OutputPath = firstExistingFile(jobDir, "output_")
		} else {
			job.Metadata.Output.DownloadURL = ""
		}
		interrupted := job.Metadata.Status == "queued" || job.Metadata.Status == "running"
		if interrupted {
			job.Metadata.Status = "failed"
			job.Metadata.Error = &core.APIError{
				Code:      "job_interrupted",
				Message:   "서버 재기동으로 작업이 중단되었습니다.",
				Retryable: true,
			}
		}
		s.jobs[job.ID] = cloneJob(job)
		if interrupted {
			// Best effort: a directory that cannot be written only means the next
			// start repeats the same transition, which changes nothing.
			_ = s.persistLocked(job.ID)
		}
	}
	return nil
}

// readJobRecord decodes the record stored in a job directory. It reports false
// when there is no usable record: the file is missing or not valid JSON, or the
// id inside does not match the directory, which every write path derives from the
// id and which the retention sweep therefore would never remove.
func readJobRecord(jobDir, expectedID string) (*core.JobRecord, bool) {
	raw, err := os.ReadFile(filepath.Join(jobDir, "job.json"))
	if err != nil {
		return nil, false
	}
	var job core.JobRecord
	if err := json.Unmarshal(raw, &job); err != nil {
		return nil, false
	}
	if job.ID != expectedID {
		return nil, false
	}
	return &job, true
}

// recordTempName is where a new record is staged before it replaces job.json.
// Nothing reads it: readJobRecord only opens job.json, and firstExistingFile only
// matches the input_/output_ prefixes, so a leftover from a crash is neither
// mistaken for the record nor for a document. The next persist overwrites it.
const recordTempName = "job.json.tmp"

// persistLocked writes the in-memory record to disk. The caller holds s.mu.
//
// The record is written to a temporary file and renamed over job.json rather than
// written in place, because an in-place write truncates the file first and a
// process killed between the truncate and the write (OOM kill, SIGKILL, a disk
// that fills up) leaves an empty or cut-off record behind. load treats such a
// record as an orphan and removes the whole directory, including a masked result
// that was already written, so a job that died on its final save would vanish
// with a 404 instead of showing up as interrupted and retryable. A rename either
// replaces the file or leaves the previous record untouched. This guards against
// the process dying, not against power loss; there is no fsync.
func (s *Store) persistLocked(jobID string) error {
	job, ok := s.jobs[jobID]
	if !ok {
		return nil
	}
	jobDir := filepath.Join(s.root, jobID)
	if err := os.MkdirAll(jobDir, 0o755); err != nil {
		return err
	}
	raw, err := json.MarshalIndent(job, "", "  ")
	if err != nil {
		return err
	}
	tempPath := filepath.Join(jobDir, recordTempName)
	if err := os.WriteFile(tempPath, raw, 0o644); err != nil {
		return err
	}
	if err := os.Rename(tempPath, filepath.Join(jobDir, "job.json")); err != nil {
		_ = os.Remove(tempPath)
		return err
	}
	return nil
}

func cloneJob(job *core.JobRecord) *core.JobRecord {
	if job == nil {
		return nil
	}
	copyJob := *job
	copyJob.Metadata.PIISummary = append([]core.PIISummaryItem(nil), job.Metadata.PIISummary...)
	copyJob.Metadata.MaskPolicy.AppliedRules = append([]string(nil), job.Metadata.MaskPolicy.AppliedRules...)
	copyJob.Metadata.MaskPolicy.SupportedRules = append([]string(nil), job.Metadata.MaskPolicy.SupportedRules...)
	return &copyJob
}

func firstExistingFile(dir, prefix string) string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return ""
	}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		if len(entry.Name()) >= len(prefix) && entry.Name()[:len(prefix)] == prefix {
			return filepath.Join(dir, entry.Name())
		}
	}
	return ""
